### Additional information

## Root Cause
```typescript
    private async getRegistryFromPackageManager(): Promise<string | undefined> {
        try {
          const packageManagerName = await packageManager.getPreferred(this.cwd);
          if (!packageManagerName) return undefined;

          const registryCommands = {
            yarn: ['config', 'get', 'npmRegistryServer'], // <-- HERE
            npm: ['config', 'get', 'registry'],
          } as const;

          const command = registryCommands[packageManagerName as keyof typeof registryCommands];
          if (!command) {
            this.logger.warn(`Unsupported package manager: ${packageManagerName}`);
            return undefined;
          }

          const { stdout } = await execa(packageManagerName, command, { timeout: 10_000 });
          return stdout.trim() || undefined;
        } catch (error) {
          this.logger.warn('Failed to determine registry URL from package manager');
          return undefined;
        }
      }
```


## Proposed Fix
Implement a fallback mechanism in `getRegistryFromPackageManager()`:

```typescript
  private async getRegistryFromPackageManager(): Promise<string | undefined> {
    try {
      const packageManagerName = await packageManager.getPreferred(this.cwd);
      if (!packageManagerName) return undefined;

      // Handle Yarn (supports both v1 Classic and v2+ Berry)
      if (packageManagerName === 'yarn') {
        // Try Yarn v2+ (Berry) registry key first
        try {
          const { stdout } = await execa('yarn', ['config', 'get', 'npmRegistryServer'], { 
            timeout: 10_000 
          });
          const registry = stdout.trim();

          // Yarn v2+ returns the string "undefined" when the config key doesn't exist
          // Only use this value if it's a valid registry URL
          if (registry && registry !== 'undefined') {
            return registry;
          }
        } catch {
          // Yarn v1 doesn't recognize 'npmRegistryServer', continue to v1 fallback
        }

        // Fallback to Yarn v1 (Classic) registry key
        const { stdout } = await execa('yarn', ['config', 'get', 'registry'], { 
          timeout: 10_000 
        });
        return stdout.trim() || undefined;
      }

      // Handle npm
      if (packageManagerName === 'npm') {
        const { stdout } = await execa('npm', ['config', 'get', 'registry'], { 
          timeout: 10_000 
        });
        return stdout.trim() || undefined;
      }

      // Unsupported package manager
      this.logger.warn(`Unsupported package manager: ${packageManagerName}`);
      return undefined;

    } catch (error) {
      this.logger.warn('Failed to determine registry URL from package manager');
      return undefined;
    }
  }
```

## Temporary Workaround

Until this issue is resolved, users can work around the registry detection failure by creating an empty `package-lock.json` file in the same directory. The presence of package-lock.json causes the upgrade tool to use npm's registry detection (which works correctly), instead of the broken Yarn v1 detection.


